 input.setText(std::string(129,'1'),false);refuse([&]{form.read();});input.setText("15.123456789012345678901234567890",false);unknown.setToggleState(true,juce::dontSendNotification);const auto report=form.read();check(field(report,"reported_seconds").null(),"Explicit Unknown did not roundtrip null");check(!field(report,"released").boolean(),"Unknown discharged release");check(input.getText()=="15.123456789012345678901234567890","Unknown erased prior typed token");unknown.setToggleState(false,juce::dontSendNotification);check(std::get<json::Number>(field(form.read(),"reported_seconds").data).token=="15.123456789012345678901234567890","Unknown toggle rounded prior entry");
 auto stale=input.onTextChange;owned=false;const auto before=edits;stale();check(edits==before&&!form.valueAt("input/reported_seconds"),"Stale owner number callback/read escaped fence");refuse([&]{form.read();});owned=true;form.configure(object(schema()),{},fence);stale();check(edits==before,"Old decimal callback touched new form");check(control<juce::TextEditor>(form,"typed-field-input/reported_seconds").getText().isEmpty(),"Fresh pass retained old number");
 for(const auto& limits:std::vector<std::pair<std::string,std::string>>{{"15.000000000000000000000000000001","15.000000000000000000000000000002"},{"-15.000000000000000000000000000002","-15.000000000000000000000000000001"},{"1e-20","1.00000000000000000000000001e-20"},{"-1e3","-1e-20"},{"0","0"}}){
  form.configure(schema(false,number(limits.first),number(limits.second)),{},fence);auto& entry=control<juce::TextEditor>(form,"typed-field-input");entry.setText(ju(limits.first),false);check(form.read()==number(limits.first),"Exact lower bound refused");entry.setText(ju(limits.second),false);check(form.read()==number(limits.second),"Exact upper bound refused");
 }
 form.configure(schema(false,number("15.000000000000000000000000000001"),number("15.000000000000000000000000000002")),{},fence);auto& precise=control<juce::TextEditor>(form,"typed-field-input");for(const auto* bad:{"15","15.0000000000000000000000000000009","15.0000000000000000000000000000021","15.000000000000000000000000000003"}){precise.setText(bad,false);refuse([&]{form.read();});}
 form.configure(schema(false,number("-15.000000000000000000000000000002"),number("-15.000000000000000000000000000001")),{},fence);auto& negative=control<juce::TextEditor>(form,"typed-field-input");for(const auto* bad:{"-15","-15.000000000000000000000000000003"}){negative.setText(bad,false);refuse([&]{form.read();});}
 refuse([&]{form.configure(schema(false,number("2"),number("1")),{},fence);});refuse([&]{form.configure(schema(false,V("0"),number("1")),{},fence);});refuse([&]{form.configure(schema(false,V(json::Number{"NaN"}),number("1")),{},fence);});auto defaults=schema();defaults.object()["default"]=number("15");refuse([&]{form.configure(defaults,{},fence);});
 form.configure(O{{"type","number"},{"enum",A{number("0.125"),number("1e-5")}}},{},fence);auto& choice=control<juce::ComboBox>(form,"typed-field-input");check(choice.getSelectedId()==0&&choice.getItemText(0)=="0.125","Numeric choice was defaulted or rounded");choice.setSelectedId(2,juce::dontSendNotification);check(form.read()==number("1e-5"),"Finite number enum changed token");
